# Hand-made single-site mutants of the new production code of work package 1b.7e. Read by make_1b7e_mutants.py (exec), one list per source file; ids are prefix + number.
FILES['Sesa/Crc32C.cs'] = [
    m('C01', 'polynomial changed', 'private const uint Reflected = 0x82F63B78;', 'private const uint Reflected = 0x82F63B79;'),
    m('C02', 'hardware flag needs both CPUs', 'Sse42.X64.IsSupported || Crc32.Arm64.IsSupported;', 'Sse42.X64.IsSupported && Crc32.Arm64.IsSupported;'),
    m('C03', 'dispatch swapped (both paths give the same value)', 'HardwareAccelerated ? Hardware(crc, data, length) : Table(crc, data, length);', 'HardwareAccelerated ? Table(crc, data, length) : Hardware(crc, data, length);'),
    m('C04', 'table k built from the wrong byte', 't[(k * 256) + i] = (previous >> 8) ^ t[previous & 0xFF];', 't[(k * 256) + i] = (previous >> 8) ^ t[(previous >> 8) & 0xFF];'),
    m('C05', 'slice 7 reads table 6', 'c = t[(7 * 256) + (lo & 0xFF)]', 'c = t[(6 * 256) + (lo & 0xFF)]'),
    m('C06', 'slice 3 reads table 2', '^ t[(3 * 256) + (hi & 0xFF)]', '^ t[(2 * 256) + (hi & 0xFF)]'),
    m('C07', 'tail shifts by 7', 'for (; at < length; at++) c = t[(c ^ data[at]) & 0xFF] ^ (c >> 8);', 'for (; at < length; at++) c = t[(c ^ data[at]) & 0xFF] ^ (c >> 7);'),
    m('C08', 'table loop leaves the last full word to the tail loop (same value)', 'for (; at + 8 <= length; at += 8)\n        {\n            uint lo', 'for (; at + 8 < length; at += 8)\n        {\n            uint lo'),
    m('C09', 'hardware unrolled read at +15', 'Sse42.X64.Crc32(c64, BinaryPrimitives.ReadUInt64LittleEndian(new ReadOnlySpan<byte>(data + at + 16, 8)))', 'Sse42.X64.Crc32(c64, BinaryPrimitives.ReadUInt64LittleEndian(new ReadOnlySpan<byte>(data + at + 15, 8)))'),
    m('C10', 'hardware unrolled step of 31', 'for (; at + 32 <= length; at += 32)', 'for (; at + 32 <= length; at += 31)'),
    m('C11', 'hardware tail reads byte 0', 'for (; at < length; at++) c = Sse42.Crc32(c, data[at]);', 'for (; at < length; at++) c = Sse42.Crc32(c, data[0]);'),
    m('C12', 'table path starts from the value, not its complement', 'uint c = ~crc;\n        uint[] t = Tables;', 'uint c = crc;\n        uint[] t = Tables;'),
    m('C13', 'table path returns the value uncomplemented', 'return ~c;\n    }\n\n    private static uint Hardware', 'return c;\n    }\n\n    private static uint Hardware'),
    m('C14', 'Compute starts from 1', 'internal static uint Compute(ReadOnlySpan<byte> data) => Append(0, data);', 'internal static uint Compute(ReadOnlySpan<byte> data) => Append(1, data);'),
    m('C15', 'the hardware path no longer refuses without the CPU', 'if (!HardwareAccelerated) throw new PlatformNotSupportedException("this CPU has no CRC-32C instruction");', ''),
    m('C16', 'the arm64 tail reads byte 0', 'for (; at < length; at++) c = Crc32.ComputeCrc32C(c, data[at]);', 'for (; at < length; at++) c = Crc32.ComputeCrc32C(c, data[0]);'),
]

