    m('W04', 'sigma 256 is refused', 'ThrowIfGreaterThan(sigma, 256);', 'ThrowIfGreaterThan(sigma, 255);'),
    m('W05', 'a read of under one entry is accepted', 'ThrowIfLessThan(options.ReadBytes, sizeof(uint));', 'ThrowIfLessThan(options.ReadBytes, 1);'),
    m('W06', 'a window of 0 is accepted', 'ThrowIfLessThan(options.WindowBytes, 1);', 'ThrowIfLessThan(options.WindowBytes, 0);'),
