    m('W12', 'the SA range is not checked', 'if (saOffset > sa.Length - (sizeof(uint) * rows)) throw', 'if (false) throw'),
    m('W13', 'the read is not bounded by the rows', 'int readEntries = (int)Math.Min(options.ReadBytes / sizeof(uint), rows);', 'int readEntries = options.ReadBytes / sizeof(uint);'),
    m('W14', 'the SA buffer is zeroed', 'saBuf = arena.Allocate<uint>(readEntries, zero: false,', 'saBuf = arena.Allocate<uint>(readEntries, zero: true,'),
    m('W15', 'the budget is ignored', 'new BudgetedArena(options.Budget ?? new ArenaBudget(long.MaxValue), options.ArenaGuards)', 'new BudgetedArena(new ArenaBudget(long.MaxValue), options.ArenaGuards)'),
    m('W16', 'the guards are ignored', 'new BudgetedArena(options.Budget ?? new ArenaBudget(long.MaxValue), options.ArenaGuards)', 'new BudgetedArena(options.Budget ?? new ArenaBudget(long.MaxValue), null)'),
    m('W17', 'the BWT file ignores the file options', 'MappedOutputFile.Create(bwtPath, rows, options.Files)', 'MappedOutputFile.Create(bwtPath, rows, null)'),
    m('W18', 'the BWT writer is not counted', 'file.CreateWriter(options.WindowBytes, options.Counters)', 'file.CreateWriter(options.WindowBytes, null)'),
    m('W19', 'the BWT writer has the default window', 'file.CreateWriter(options.WindowBytes, options.Counters)', 'file.CreateWriter(MappedWindowWriter.DefaultWindowBytes, options.Counters)'),
    m('W20', 'the SA reads are not counted', 'new CountedFile(saPath, FileMode.Open, FileAccess.Read, options.Counters)', 'new CountedFile(saPath, FileMode.Open, FileAccess.Read, null)'),
    m('W21', 'the SA is read from offset 0', 'saOffset + (first * sizeof(uint))', 'first * sizeof(uint)'),
    m('W22', 'an entry n + 1 is accepted', 'if (p > n) throw', 'if (p > n + 1) throw'),
    m('W23', 'entries are not range checked', 'if (p > n) throw', 'if (false) throw'),
    m('W24', 'SA[0] may be any suffix', 'if (first + i == 0 && p != n) throw', 'if (first + i == 0 && p > n) throw'),
    m('W25', 'SA[0] is not checked', 'if (first + i == 0 && p != n) throw', 'if (false) throw'),
    m('W26', 'row 1 is the one checked for the empty suffix', 'if (first + i == 0 && p != n) throw', 'if (first + i == 1 && p != n) throw'),
    m('W27', 'a second zero is tolerated when later (equivalent for n > 0)', 'if (primary >= 0) throw', 'if (primary > 0) throw'),
