    m('W29', 'the primary row is one too high', 'primary = first + i;', 'primary = first + i + 1;'),
    m('W30', 'the primary row has a symbol byte', 'output[i] = 0;\n                                continue;', 'output[i] = 1;\n                                continue;'),
