    m('W41', 'the default read is 1 KiB', 'internal int ReadBytes { get; init; } = 1 << 20;', 'internal int ReadBytes { get; init; } = 1 << 10;'),
    m('W42', 'the output buffer is one entry short', 'Buf<byte> outBuf = arena.Allocate<byte>(readEntries,', 'Buf<byte> outBuf = arena.Allocate<byte>(Math.Max(1, readEntries - 1),'),
