    m('G14', 'the file is not made longer', 'stream.SetLength(newLength);', ''),
    m('G15', 'the stream refuses to share', 'using (var stream = new FileStream(Path, FileMode.Open, FileAccess.ReadWrite, FileShare.ReadWrite)) stream.SetLength(newLength);', 'using (var stream = new FileStream(Path, FileMode.Open, FileAccess.ReadWrite, FileShare.None)) stream.SetLength(newLength);'),
