    m('G18', 'the new mapping is not used', '            _map?.Dispose();\n            _map = map;', '            map.Dispose();'),
    m('G19', 'the length is not updated', '            Length = newLength;\n', ''),
    m('G20', 'the outcome is always checked', 'return free >= 0 ? ReservationOutcome.FreeSpaceChecked : ReservationOutcome.Unchecked;\n    }\n\n    /// <summary>A writer for the bytes', 'return ReservationOutcome.FreeSpaceChecked;\n    }\n\n    /// <summary>A writer for the bytes'),
    m('G21', 'the outcome is never checked', 'return free >= 0 ? ReservationOutcome.FreeSpaceChecked : ReservationOutcome.Unchecked;\n    }\n\n    /// <summary>A writer for the bytes', 'return ReservationOutcome.Unchecked;\n    }\n\n    /// <summary>A writer for the bytes'),
    m('G22', 'the source of the options is ignored', 'IReservationSource source = options?.Source ?? SystemReservationSource.Instance;\n        long growth', 'IReservationSource source = SystemReservationSource.Instance;\n        long growth'),
